"""Operating Systems — curated concept questions (each with an explanation)."""
from content.kit import C

C("OS", "Processes, Threads & Syscalls", "Concepts", [
    ("e", 1, "s", "Which of the following is NOT stored in a Process Control Block (PCB)?", ["Process state", "Program counter", "Contents of the process's entire heap", "CPU register values saved at the last context switch"], 2,
     "The PCB holds state, PC, registers, scheduling info, memory-management info (e.g. page-table pointer) and I/O status — not the heap contents themselves."),
    ("e", 1, "s", "In UNIX, which system call creates a new process by duplicating the calling process?", ["exec()", "fork()", "wait()", "spawn()"], 1, "fork() creates a child that is a copy of the parent; exec() replaces the current process image."),
    ("m", 2, "m", "Which resources are SHARED by all threads of the same process? (select all)", ["Code section", "Heap", "Open file descriptors", "Stack", "Register set"], [0, 1, 2],
     "Each thread has its own stack and register set (including PC); code, heap, globals and open files are shared."),
    ("m", 1, "s", "In the many-to-one threading model, if one user-level thread makes a blocking system call, then", ["only that thread blocks", "the entire process blocks", "the kernel creates a new kernel thread automatically", "all other threads continue to run"], 1,
     "The kernel sees only one schedulable entity, so a blocking call blocks every thread of the process."),
    ("e", 1, "s", "A process moves from the RUNNING state to the READY state when", ["it requests an I/O operation", "its time quantum expires (pre-emption)", "it terminates", "an I/O operation it was waiting for completes"], 1,
     "Running → Ready happens on pre-emption; Running → Waiting on I/O request; Waiting → Ready on I/O completion."),
    ("m", 1, "s", "A process that has terminated but whose parent has not yet called wait() is called a", ["zombie process", "orphan process", "daemon process", "swapped process"], 0,
     "Its PCB entry remains so the parent can read the exit status."),
    ("m", 1, "s", "When a parent process terminates before its child, the child becomes an", ["zombie", "orphan, adopted by init", "daemon automatically terminated", "deadlocked process"], 1, "The init (PID 1) process adopts orphans and reaps them."),
    ("m", 2, "m", "Which of the following instructions must be executed only in kernel (privileged) mode? (select all)", ["Setting the value of the timer", "Reading the system clock", "Clearing memory", "Turning off interrupts"], [0, 2, 3],
     "Reading the clock can safely be done in user mode; the others could break protection or let a process monopolise the CPU."),
    ("m", 1, "s", "An interrupt differs from a trap (software interrupt) in that an interrupt is", ["asynchronous and generated by hardware", "synchronous and generated by the running program", "always caused by an illegal instruction", "never maskable"], 0,
     "Traps/exceptions are synchronous results of executing an instruction; interrupts come from devices at arbitrary times."),
    ("h", 2, "s", "Which of the following is TRUE about a context switch between two PROCESSES compared with a switch between two THREADS of the same process?", ["The process switch is cheaper because the page table need not be changed", "The thread switch is cheaper because no address-space (page table/TLB) switch is needed", "Both cost exactly the same", "A thread switch always requires flushing the cache"], 1,
     "Threads in one process share the address space, so the MMU context and (usually) the TLB need not change."),
    ("e", 1, "s", "A system call is typically implemented through", ["a trap instruction that switches the CPU to kernel mode", "an ordinary function call within user space", "a hardware interrupt from the disk", "a signal sent by the shell"], 0, "The trap transfers control to a kernel entry point."),
    ("m", 2, "s", "Which of the following is a correct statement about the exec() family of calls?", ["The calling process's PID changes", "The calling process's address space is replaced by the new program; the PID stays the same", "A new child process is created", "Open file descriptors are always closed"], 1,
     "exec replaces the program image; the process keeps its PID (and by default its open descriptors)."),
])

C("OS", "CPU Scheduling", "Concepts", [
    ("m", 2, "m", "Which scheduling algorithms can cause STARVATION? (select all)", ["Shortest Job First", "Priority scheduling (without aging)", "Round Robin", "First Come First Served", "Shortest Remaining Time First"], [0, 1, 4],
     "Long jobs / low-priority jobs may wait forever in SJF, SRTF and priority scheduling; RR and FCFS are starvation-free."),
    ("e", 1, "s", "The 'convoy effect' is associated with", ["FCFS scheduling", "Round Robin with small quantum", "Priority scheduling", "Multilevel feedback queues"], 0, "Short processes queue behind one long CPU-bound process."),
    ("e", 1, "s", "Round Robin with a time quantum that is much larger than every CPU burst behaves like", ["FCFS", "SJF", "Priority scheduling", "SRTF"], 0, "Nobody is pre-empted, so processes run to completion in arrival order."),
    ("m", 1, "s", "For a given set of processes that all arrive at time 0, which non-preemptive algorithm gives the minimum average waiting time?", ["FCFS", "Shortest Job First", "Round Robin", "Longest Job First"], 1, "SJF is provably optimal for average waiting time."),
    ("m", 2, "m", "Which of the following are NON-preemptive scheduling policies? (select all)", ["FCFS", "Non-preemptive SJF", "Round Robin", "Shortest Remaining Time First", "Preemptive priority"], [0, 1], "RR, SRTF and preemptive priority can take the CPU away from a running process."),
    ("m", 1, "s", "In a multilevel feedback queue, a process that uses its entire quantum is usually", ["moved to a lower-priority queue", "moved to a higher-priority queue", "terminated", "moved to the I/O queue"], 0, "CPU-bound processes sink to lower queues; aging can promote starving ones."),
    ("e", 1, "s", "The dispatcher is the module that", ["gives control of the CPU to the process chosen by the short-term scheduler", "selects the next job from the job pool", "swaps processes to disk", "allocates memory to processes"], 0, "Dispatch latency = time to stop one process and start another."),
    ("m", 1, "s", "Aging is used in priority scheduling to", ["prevent starvation by gradually increasing waiting processes' priority", "reduce context-switch time", "implement time slicing", "lower the priority of I/O-bound processes"], 0, "Raising priority with waiting time guarantees eventual service."),
    ("h", 2, "s", "A system uses round-robin with quantum q and context-switch overhead s. To keep CPU efficiency (useful/total) at least 90% for CPU-bound processes, q must satisfy", ["q ≥ 9s", "q ≥ s/9", "q ≤ 9s", "q ≥ 10s"], 0, "Efficiency = q/(q+s) ≥ 0.9 ⇒ q ≥ 9s."),
])

C("OS", "Synchronization", "Concepts", [
    ("e", 1, "m", "Which three requirements must a correct solution to the critical-section problem satisfy? (select the correct ones)", ["Mutual exclusion", "Progress", "Bounded waiting", "Busy waiting", "Starvation freedom is NOT needed but deadlock is required"], [0, 1, 2], "The classic requirements are mutual exclusion, progress and bounded waiting."),
    ("m", 1, "s", "Peterson's algorithm for two processes uses", ["two flag variables and a turn variable", "a single test-and-set instruction", "semaphores initialised to 0", "disabling interrupts"], 0, "flag[i] shows interest; turn breaks ties."),
    ("m", 2, "s", "The simple test-and-set lock does NOT guarantee", ["mutual exclusion", "bounded waiting", "atomicity of the instruction", "progress when no one is in the critical section"], 1, "A process can be starved if others repeatedly win the lock."),
    ("e", 1, "s", "A semaphore's wait() and signal() operations must be", ["atomic", "executed only by the kernel's scheduler", "implemented with busy waiting only", "limited to binary values"], 0, "Otherwise the semaphore's own value would be a race condition."),
    ("m", 2, "s", "In the bounded-buffer producer–consumer solution with semaphores empty (=N), full (=0) and mutex (=1), swapping the order of wait(empty) and wait(mutex) in the PRODUCER may cause", ["deadlock when the buffer is full", "a buffer overflow", "starvation of the consumer only", "no problem at all"], 0,
     "The producer can hold mutex while waiting for empty; the consumer then can never get mutex to free a slot."),
    ("m", 1, "s", "In the first readers–writers problem (readers have priority) the main drawback is", ["writers may starve", "readers may starve", "deadlock is unavoidable", "the buffer may overflow"], 0, "A steady stream of readers keeps the writer waiting."),
    ("m", 2, "s", "Five philosophers share five forks; each needs two forks to eat. Which change guarantees deadlock freedom?", ["Allow at most four philosophers to sit at the table", "Make every philosopher pick the left fork first", "Increase the thinking time", "Use a binary semaphore per philosopher"], 0, "With at most 4 seated, at least one can get both forks."),
    ("m", 1, "s", "In a monitor", ["only one process can be active inside at a time", "any number of processes may execute monitor procedures concurrently", "condition variables hold counts like semaphores", "mutual exclusion must be programmed explicitly"], 0, "Mutual exclusion is automatic; condition variables are for waiting."),
    ("h", 2, "s", "Priority inversion occurs when", ["a low-priority process holding a lock blocks a high-priority process while a medium-priority process runs", "two processes have the same priority", "a high-priority process starves a low-priority one", "the scheduler aging increases priority too fast"], 0, "Priority inheritance is the standard remedy."),
    ("h", 2, "s", "Which statement about spinlocks is correct?", ["On a single-processor system spinning for a lock held by a pre-empted process is wasteful", "They are always better than blocking locks", "They allow bounded waiting with no extra mechanism", "They require no atomic instruction"], 0, "The holder cannot release the lock while the only CPU is busy spinning."),
    ("h", 2, "m", "Two processes use a shared integer X and semaphore S (initially 1). Which of the following make the update X = X + 1 safe? (select all)", ["wait(S); X = X + 1; signal(S)", "Disable interrupts around X = X + 1 on a uniprocessor", "Use an atomic fetch-and-add on X", "X = X + 1 without protection because it is a single C statement"], [0, 1, 2], "A C statement is not atomic; load–add–store can interleave."),
])

C("OS", "Deadlocks", "Concepts", [
    ("e", 1, "m", "Which are the four necessary conditions for deadlock? (select all that apply)", ["Mutual exclusion", "Hold and wait", "No pre-emption", "Circular wait", "Starvation"], [0, 1, 2, 3], "All four must hold simultaneously."),
    ("m", 1, "s", "The Banker's algorithm is an example of deadlock", ["avoidance", "prevention", "detection", "ignoring (ostrich algorithm)"], 0, "It grants a request only if the resulting state is safe."),
    ("m", 2, "s", "In a resource-allocation graph where every resource has a SINGLE instance, a cycle", ["is both necessary and sufficient for deadlock", "is necessary but not sufficient", "is sufficient but not necessary", "never indicates deadlock"], 0, "With multiple instances a cycle is only necessary."),
    ("m", 1, "s", "Which statement is TRUE?", ["Every unsafe state leads to deadlock", "A deadlocked state is an unsafe state", "A safe state may still lead to deadlock", "Safe state is the same as the no-cycle condition in all cases"], 1, "Unsafe means deadlock is possible, not certain; deadlock ⊂ unsafe."),
    ("m", 1, "s", "Imposing a total ordering on resource types and requiring requests in increasing order prevents", ["circular wait", "hold and wait", "mutual exclusion", "no pre-emption"], 0, "A cycle would require some process to request a lower-numbered resource."),
    ("h", 2, "s", "Which of the following breaks the 'hold and wait' condition?", ["Requiring a process to request all its resources before it begins execution", "Pre-empting resources from waiting processes", "Numbering resources", "Using spooling for printers"], 0, "A process never holds some resources while waiting for others."),
    ("m", 1, "s", "A wait-for graph is obtained from the resource-allocation graph by", ["removing resource nodes and collapsing edges between processes", "adding request edges for all resources", "reversing every edge", "removing process nodes"], 0, "Used for deadlock detection with single-instance resources."),
])

C("OS", "Memory Management & Paging", "Concepts", [
    ("e", 1, "s", "Internal fragmentation is characteristic of", ["paging (and fixed partitions)", "segmentation with variable-size segments", "dynamic partitioning", "contiguous allocation of variable-size holes"], 0, "The last page of a process is rarely full."),
    ("e", 1, "s", "External fragmentation can be reduced by", ["compaction", "using a larger page size", "increasing the TLB size", "using a smaller cache"], 0, "Compaction moves processes together to make one large hole (needs dynamic relocation)."),
    ("m", 1, "s", "Belady's anomaly can occur in", ["FIFO page replacement", "LRU page replacement", "Optimal page replacement", "All stack algorithms"], 0, "LRU and OPT are stack algorithms, so they do not exhibit the anomaly."),
    ("m", 1, "s", "Thrashing is best described as", ["the system spending most of its time swapping pages instead of executing", "too many TLB hits", "excess internal fragmentation", "a deadlock in the memory manager"], 0, "Caused by too high a degree of multiprogramming; the working-set model controls it."),
    ("m", 1, "s", "A TLB miss", ["requires a page-table walk, but does not imply a page fault", "always raises a page fault", "means the page is on disk", "flushes the cache"], 0, "A page fault occurs only if the page-table entry is invalid."),
    ("m", 2, "s", "An inverted page table", ["has one entry per physical frame and is usually searched with a hash", "has one entry per virtual page of every process", "eliminates the TLB", "increases the memory needed for page tables"], 0, "It saves memory at the cost of slower lookup."),
    ("h", 2, "s", "Copy-on-write is used by fork() so that", ["parent and child share pages until one of them writes", "the child gets a full copy of memory immediately", "the child shares the stack but not the heap", "pages are never duplicated"], 0, "It avoids unnecessary copying, especially when exec() follows."),
    ("m", 1, "s", "Increasing the page size generally", ["increases internal fragmentation and reduces page-table size", "reduces internal fragmentation and increases page-table size", "has no effect on page-table size", "eliminates TLB misses"], 0, "Bigger pages → fewer entries, more waste in the last page."),
    ("m", 2, "m", "Which of the following are page-replacement algorithms that approximate LRU using hardware support? (select all)", ["Second-chance (clock) using a reference bit", "Additional-reference-bits algorithm", "FIFO", "Optimal"], [0, 1], "FIFO ignores recency; OPT is unrealisable."),
    ("h", 2, "s", "In demand paging, when a page fault occurs the OS first", ["checks whether the reference is valid, then finds a free frame and reads the page from disk", "kills the process", "flushes the entire TLB and restarts", "updates the file-system inode"], 0, "Then it updates the page table and restarts the faulting instruction."),
    ("e", 1, "s", "Temporal locality means", ["recently referenced locations are likely to be referenced again soon", "nearby addresses are likely to be referenced together", "pages are referenced in a fixed order", "programs reference only their stack"], 0, "Spatial locality is the neighbouring-address principle."),
])

C("OS", "File Systems & Disk Scheduling", "Concepts", [
    ("e", 1, "s", "A major disadvantage of contiguous file allocation is", ["external fragmentation and difficulty in growing files", "slow sequential access", "need for index blocks", "inability to support direct access"], 0, "It offers fast sequential and direct access though."),
    ("e", 1, "s", "Which allocation method suffers from pointer overhead and slow direct access unless a FAT is used?", ["Linked allocation", "Contiguous allocation", "Indexed allocation", "Extent-based allocation"], 0, "Reaching block k requires following k pointers."),
    ("m", 2, "m", "Which statements about hard and symbolic (soft) links in UNIX are TRUE? (select all)", ["A hard link refers to the same inode as the original name", "Removing the original name of a file leaves a hard link usable", "A symbolic link can point to a directory on another file system", "A hard link can span different file systems"], [0, 1, 2], "Hard links are same-file-system only; symbolic links store a path."),
    ("m", 1, "s", "RAID level 5 provides", ["block-level striping with distributed parity, tolerating one disk failure", "pure striping without redundancy", "mirroring only", "dedicated parity disk with bit-level striping"], 0, "RAID 0 = striping, RAID 1 = mirroring."),
    ("m", 1, "s", "SSTF disk scheduling can suffer from", ["starvation of far-away requests", "high rotational latency", "unfairness only for sequential files", "excess head movement for the closest request"], 0, "New close requests can keep postponing distant ones."),
    ("m", 1, "s", "C-SCAN scheduling provides", ["more uniform wait times than SCAN", "the minimum total head movement always", "no starvation but only for reads", "shorter seeks than SSTF always"], 0, "The head services in one direction and jumps back."),
    ("h", 2, "s", "A file system uses 12 direct block pointers and one single-indirect pointer; block size is 4 KB and a pointer is 4 bytes. The maximum file size is", ["(12 + 1024) × 4 KB = 4144 KB", "12 × 4 KB = 48 KB", "(12 + 1024²) × 4 KB", "1024 × 4 KB = 4096 KB"], 0, "A 4 KB block holds 1024 pointers: (12 + 1024) blocks."),
    ("m", 1, "s", "Spooling is used mainly to", ["overlap I/O of one job with computation of others by buffering on disk", "speed up the CPU", "implement virtual memory", "avoid deadlocks in files"], 0, "E.g., print spooling."),
    ("h", 2, "s", "DMA improves I/O performance because", ["the CPU is not involved in each word transfer, only at start and completion", "it removes the need for device drivers", "it increases the bus width", "it makes memory faster"], 0, "The controller moves data directly between device and memory."),
])
